/* ------------------------------ 实例化（仅用于花瓣 / 草 / 砕石等海量同质件） ------------------------------ */
function inst(geo, mat, count, cb, { name = '', cast = true, receive = false } = {}) {
  const im = new InstancedMesh(geo, mat, count);
  im.name = name;
  im.castShadow = cast;
  im.receiveShadow = receive;
  const d = new Object3D();
  const col = new Color(1, 1, 1);
  for (let i = 0; i < count; i++) {
    d.position.set(0, 0, 0);
    d.rotation.set(0, 0, 0);
    d.scale.set(1, 1, 1);
    col.setRGB(1, 1, 1);
    cb(i, d, mulberry32(i * 977 + 13), col);
    d.updateMatrix();
    im.setMatrixAt(i, d.matrix);
    im.setColorAt(i, col);
  }
  im.instanceMatrix.needsUpdate = true;
  if (im.instanceColor) im.instanceColor.needsUpdate = true;
  im.computeBoundingSphere();
  return im;
}

/* ------------------------------ 其它 ------------------------------ */
const rand = (seed) => mulberry32(seed);
