  /* ---------- 樹木枡 ---------- */
  const pits = [
    [-6.2, 15.3, 'gravel'],
    [5.2, 15.3, 'grate'],
    [-13.4, 6.35, 'gravel'],
    [10.6, 6.4, 'gravel'],
    [10.6, -2.2, 'grate'],
  ];
  pits.forEach(([x, z, k], i) => treePit(g, { x, z, y, r: 0.44, kind: k, seed: 100 + i }));

