/** 电线档距：把 POLES/SPANS 换算成 power-lines 资产需要的 a/b 端点 */
function spanOptions(entry) {
  const i = entry.options.span;
  const [pa, pb] = SPANS[i];
  const A = POLES.find((p) => p.id === pa);
  const B = POLES.find((p) => p.id === pb);
  return { ...entry.options, a: [A.x, A.z], b: [B.x, B.z], aHeight: A.h, bHeight: B.h, aRot: A.rotY, bRot: B.rotY, config: 'primary', sag: 0.6 };
}


async function placeAll(assets, engine, { budgetMs = 12, overflowTol = 0.06, onProgress } = {}) {
  const missing = [];
  const overflow = [];
  const poleOk = {};   // 电线档距只有在两端电线杆真的落了地时才成立
  const bb = new Box3();
  let i = 0;
  // 只保留红线矩形内的资产。x 向放 1.0 m 余量（西侧电柱列 P0/邮筒的原点刚好压在
  // 内容边界上，严格裁剪会把整排电线杆切掉）；z 向不放余量（北法面与鉄塔、南侧桜並木
  // 的原点都紧贴边界，一旦放余量就会把它们留在画面里）。
  const MX = 1.0, MZ = 0;
  const inCrop = (x, z) => x >= CROP.x0 - MX && x <= CROP.x1 + MX && z >= CROP.z0 - MZ && z <= CROP.z1 + MZ;
  // 时间预算式让出，而不是「每 N 个让一次」：单个资产可以长达数百毫秒
  // （drink-fridge 上万 Mesh、樱花数千花瓣卡），固定步长仍会把主线程连续锁死几十秒，
  // 期间画面不动、OrbitControls 收不到指针事件 —— 表现就是「很卡，无法移动」。
  let last = performance.now();
  for (const entry of PLACEMENT) {
    i++;
    // 进度按清单序号报，而不是按「已落地件数」：被裁剪框剔除的件不占时间，
    // 用落地数计数会让进度条在南侧花树那一段突然停滞。
    onProgress?.(i, PLACEMENT.length);
    if (performance.now() - last > budgetMs) {
      await yieldToBrowser();
      last = performance.now();
    }
    const [file, pos, rotY, scale, options, name] = entry;
    const t0 = performance.now();
    const mod = await resolveModule(file);
    if (!mod) {
      missing.push(file);
      continue;
    }
    const opt = file.endsWith('power-lines') ? spanOptions({ options }) : { ...options };
    // 店内商品、贩卖机里的饮料：标签色带只有 2 cm 上下，是需求点名「每层都要看得见」的内容，
    // 不能被远景 LOD 的 26 px 剔除吃掉 —— 给这些资产单独更严（更小）的阈值。
    if (/^interior\//.test(file) || /^products\//.test(file) || /vending-machine/.test(file)) opt.lodPx = 16;
    const p = file === null || pos === null ? null : pos;
    // 裁剪框过滤：电线档距要两端都在框内，否则线头会悬在空处
    if (file.endsWith('power-lines')) {
      const [pa, pb] = SPANS[opt.span];
      if (!inCrop(opt.a[0], opt.a[1]) || !inCrop(opt.b[0], opt.b[1])) continue;
      if (!poleOk[pa] || !poleOk[pb]) continue;   // 端杆被裁掉 → 这一档电线一并去掉
    } else if (p && !inCrop(p[0], p[2])) {
      continue;
    }
    let o = null;
    try {
      if (file.endsWith('power-lines')) {
        // 资产内部已把档距方向烘进局部坐标：装配层只平移，绝不再旋转
        o = mod.build(opt);
        o.position.set((opt.a[0] + opt.b[0]) / 2, 0, (opt.a[1] + opt.b[1]) / 2);
        o.name = name;
        assets.add(o);
      } else {
        o = place(assets, mod, { pos: p, rotY, scale, options: opt, name });
      }
    } catch (e) {
      console.warn('[placement] build failed:', file, e && e.message);
      missing.push(file + ' (throw)');
      traceMark('asset', (name || file) + ' (throw)', t0);
      continue;
    }
    /* 中心在框内 ≠ 东西在框内：树冠、屋簷、4 m 绿篱都会伸出台座，
       而台座是一块实心板 —— 伸出去的部分就是「悬在空中的杂物」。
       量实际包围盒，越界的整件不落地，并记录越界量供 tools/inspect 核对后改坐标。 */
    if (o) {
      bb.makeEmpty();
      bb.setFromObject(o);
      if (!bb.isEmpty()) {
        const over = Math.max(CROP.x0 - bb.min.x, bb.max.x - CROP.x1, CROP.z0 - bb.min.z, bb.max.z - CROP.z1);
        if (over > overflowTol) {
          if (o.parent) o.parent.remove(o);
          overflow.push({ name: name || file, over: +over.toFixed(2) });
          traceMark('asset', (name || file) + ' (越界丢弃)', t0);
          continue;
        }
      }
    }
    traceMark('asset', name || file, t0);
    const pid = /^pole-(P\d)$/.exec(name || '');
    if (pid) poleOk[pid[1]] = true;
  }
  if (engine) {
    engine.missing = [...new Set(missing)];
    engine.overflow = overflow;
    engine.placedCount = assets.children.length;
  }
  return assets;
}

// 距离分层显示（LOD）：远看小于若干像素的零件与描边壳按需隐藏
// 目的：保留「每个物件独立建模、不合并网格」的前提下维持流畅帧率。
// 规则（按资产实例到相机的距离）：
//   · 反壳描边：> hullRange 米隐藏（画面上仅一两像素，隐藏后由屏幕空间描边接管轮廓）
//   · 屏幕尺寸：投影后小于 pxThreshold 像素的独立零件隐藏（螺栓/标签/小花等），靠近自动回归
// 只切换 visible，绝不改动几何、不合并网格。

const DEFAULTS = { hullRange: 16, pxThreshold: 9, interval: 0.2, hysteresis: 1.14 };

/** 升序数组里第一个 ≥ v 的下标（即 < v 的个数） */
function lowerBound(arr, v) {
  let lo = 0,
    hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] < v) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/**
 * 静态子树优化：装配完成后，除被 sway 摆动的组（及其子树）外，
 * 全部节点关闭 matrixWorldAutoUpdate —— 每帧不再遍历数万个静止节点。
 */
function markStatic(root) {
  // 先烘好世界矩阵（此刻 auto update 仍开着），再关闭逐帧更新。
  // 顺序反了会留下恒等 matrixWorld：three 的 updateMatrixWorld() 对
  // matrixWorldAutoUpdate===false 的节点连 force 都不重算，只能靠别处
  // 偶然调用的 updateWorldMatrix() 补救 —— 装配体检工具就会被坑到。
  root.updateMatrixWorld(true);
  const swayers = [];
  root.traverse((n) => {
    if (n.userData?.sway) swayers.push(n);
    n.matrixWorldAutoUpdate = false;
    n.matrixAutoUpdate = false;
  });
  for (const sw of swayers) {
    sw.matrixAutoUpdate = true;
    sw.matrixWorldAutoUpdate = true;
    sw.traverse((c) => {
      c.matrixWorldAutoUpdate = true;
      if (c !== sw && c.userData?.sway) c.matrixAutoUpdate = true;
    });
  }
  return root;
}

function installLod(engine, root, opts = {}) {
  const cfg = { ...DEFAULTS, ...opts };
  const groups = [];
  const tmpBox = new Box3();
  const tmpSize = new Vector3();
  const tmpScale = new Vector3();
  // 像素 → 世界尺寸换算：px = maxDim / dist * (H / (2 tan(fov/2)))
  const pxToScale = () => engine.renderer.getDrawingBufferSize(new Vector2()).y / (2 * Math.tan(MathUtils.degToRad(engine.camera.fov * 0.5)));

  function collectInstances(node) {
    // 分组必须落在「资产实例」这一层。world 的直接子节点只有 map / assets 两个图层，
    // 若按图层成组，整场景会塌成 2 个组：组心＝场景中心、组半径≈21 m，
    // 于是 d = dist - radius ≈ 0.9 m，尺寸阈值 limit = d/unit 跟着塌到 1 cm ——
    // 结果一个零件都隐藏不了（实测 48096/48096 全可见）。
    for (const layer of node.children) {
      if (!layer.isObject3D) continue;
      const units = layer.name === 'map' || layer.name === 'assets' ? layer.children : [layer];
      for (const child of units) {
      const hulls = [];
      const parts = [];
      child.updateMatrixWorld(true);
      child.traverse((n) => {
        if (!n.isMesh) return;
        const g = n.geometry;
        if (!g) return;
        if (n.isInstancedMesh) {
          // 实例批次按「批次自身的包围球直径」判断，不按单个零件的尺寸：
          // 一批花瓣摊开是 0.6 m 的树冠、一排饮料是 1 m 的货架，远景看到的正是这坨整体；
          // 若按单件（花瓣 4 cm）判定，整批会在中景被剔掉，树冠和货架会凭空消失。
          // 只有确实缩成一团的批次（一把螺丝、一排标签在同一 5 cm 内）才会被剔。
          if (n.userData?.isHull) return;
          if (!n.boundingSphere) n.computeBoundingSphere();
          const bs = n.boundingSphere;
          if (!bs || !Number.isFinite(bs.radius)) return;
          n.getWorldScale(tmpScale);
          const maxDim = bs.radius * 2 * Math.max(tmpScale.x, tmpScale.y, tmpScale.z);
          if (maxDim > 0) parts.push({ n, maxDim });
          return;
        }
        if (n.userData?.isHull) {
          hulls.push(n);
          return;
        }
        if (!g.boundingBox) g.computeBoundingBox();
        g.boundingBox.getSize(tmpSize);
        n.getWorldScale(tmpScale);
        const maxDim = Math.max(tmpSize.x * tmpScale.x, tmpSize.y * tmpScale.y, tmpSize.z * tmpScale.z);
        if (maxDim > 0) parts.push({ n, maxDim });
      });
      if (!hulls.length && !parts.length) continue;
      try {
        tmpBox.setFromObject(child);
      } catch {
        continue;
      }
      if (tmpBox.isEmpty()) continue;
      parts.sort((a, b) => a.maxDim - b.maxDim);
      const sizes = parts.map((p) => p.maxDim);
      groups.push({
        hulls,
        parts,
        sizes,
        // 资产可以自己申报更严的剔除阈值（userData.lodPx）：便利店内部与贩卖机里的
        // 饮料标签是需求点名的「每层都要看得见」，2 cm 的色带不能被远景剔除吃掉。
        px: Number.isFinite(child.userData?.lodPx) ? child.userData.lodPx : null,
        center: tmpBox.getCenter(new Vector3()),
        radius: Math.max(0.35, tmpBox.getSize(new Vector3()).length() * 0.42),
        hullOn: null,
        cut: -1,
      });
      }
    }
  }
  collectInstances(root);

  let acc = 0;
  let active = true;

  engine.onUpdate((dt) => {
    if (!active) return;
    acc += dt;
    if (acc < cfg.interval) return;
    acc = 0;
    const cam = engine.camera.position;
    const pxScale = pxToScale();                       // 1 m 在 1 m 处占多少像素
    for (const g of groups) {
      const d = Math.max(0.2, cam.distanceTo(g.center) - g.radius);
      // 描边壳开关加滞回：临界距离上逐帧开关就是「一闪一闪」的直接来源
      const hr = cfg.hullRange;
      const wantHull = g.hullOn == null ? d < hr : g.hullOn ? d < hr * 1.06 : d < hr * 0.94;
      if (g.hullOn !== wantHull) {
        g.hullOn = wantHull;
        for (let i = 0; i < g.hulls.length; i++) g.hulls[i].visible = wantHull;
      }
      /* 零件隐藏也要滞回：必须隐藏的前缀 = size < limit；已隐藏的零件只要 size < limit×带宽
         就维持原状。相机在临界距离上轻微推进/后退（含惯性拖尾）时，
         没有带宽的话每一帧都会翻一批 visible，画面持续闪烁，且 visible 集合抖动
         还会让 draw calls 上下跳。 */
      const limit = (d * (g.px ?? cfg.pxThreshold)) / pxScale;   // 小于阈值的零件尺寸上限（米）
      const mustHide = lowerBound(g.sizes, limit);
      const mayKeep = lowerBound(g.sizes, limit * cfg.hysteresis);
      const prev = g.cut < 0 ? mustHide : g.cut;
      const lo = Math.min(mayKeep, Math.max(mustHide, prev));
      if (lo !== g.cut) {
        const from = Math.min(g.cut, lo),
          to = Math.max(g.cut, lo);
        for (let i = Math.max(0, from); i < to; i++) g.parts[i].n.visible = i >= lo;
        g.cut = lo;
      }
    }
  });

  return {
    groups,
    get stats() {
      let hulls = 0, hullOn = 0, parts = 0, hidden = 0;
      for (const g of groups) {
        hulls += g.hulls.length;
        parts += g.parts.length;
        if (g.hullOn) hullOn += g.hulls.length;
        hidden += Math.max(0, g.cut);
      }
      return { groups: groups.length, hulls, hullOn, parts, partsHidden: hidden };
    },
    set(enabled) {
      if (enabled === active) return;
      active = enabled;
      if (enabled) {
        acc = cfg.interval;
        return;
      }
      for (const g of groups) {
        for (const h of g.hulls) h.visible = true;
        for (const p of g.parts) p.n.visible = true;
        g.hullOn = true;
        g.cut = -1;
      }
    },
    ranges: cfg,
  };
}

// 世界组装：地图层 + 资产摆放（坐标取自 docs/LAYOUT.md / plan.js）
// 每个资产来自独立模块文件；此处只做 import 与落位。几何数据永不改写、永不 merge；
// 允许的是「同一几何+同一材质的实例列表拼接」（InstancedMesh，逐件变换仍独立）。

/** 落位工具 */
function place(parent, mod, { pos = [0, 0, 0], rotY: ry = 0, scale = 1, options = {}, name } = {}) {
  const o = mod.build(options);
  o.position.set(pos[0], pos[1], pos[2]);
  o.rotation.y = (ry * Math.PI) / 180;
  if (Array.isArray(scale)) o.scale.set(scale[0], scale[1], scale[2]);
  else if (scale !== 1) o.scale.setScalar(scale);
  if (name) o.name = name;
  if (options.lodPx) o.userData.lodPx = options.lodPx;   // 该资产的 LOD 剔除阈值覆盖（见 core/lod.js）
  parent.add(o);
  // 变换定稿：先修剪无价值的小描边壳，再折叠同类零件（资产内部可能还会改 lean 等）
  const t0 = performance.now();
  pruneHulls(o, options.hullMin ?? 0.16);
  // min 2：两个完全相同的零件（同一几何、同一材质、同一渲染状态）并成一次绘制调用
  // 就已经省一次 8.8 µs 的提交；零件仍是独立实例，几何数据不改写。
  autoInstance(o, { min: 2 });
  // 资产普遍「每个小群组 inst() 一次」（樱花每个花房一套花瓣/叶），
  // 同几何+同材质的实例再并一次才能把 draw call 压下来 —— 见 kit.mergeInstances
  mergeInstances(o);
  traceMark('misc', '收尾 ' + (name || mod.id || ''), t0);
  return o;
}

async function buildWorld(engine) {
  const world = grp('world');
  setWorldClip(CROP);   // 必须在任何地图模块之前

  /* ---------- 地图层 ---------- */
  const map = grp('map');
  // 每个地图模块后真正让出一帧（rAF，不是微任务——微任务不会让浏览器绘制/派发指针事件）：
  // 底座/路网/站台各自要建上万图元，串起来就是十几秒主线程死锁，期间画面拖不动。
  const MAP_LAYERS = 10;
  let mapDone = 0;
  const [m0, m1] = BOOT_PHASES.map;
  const mk = async (n, f) => {
    const t0 = performance.now();
    map.add(f());
    traceMark('map', n, t0);
    engine?.markProgress(m0 + (m1 - m0) * (++mapDone) / MAP_LAYERS, '铺设地基与路网');
    await yieldToBrowser();
  };
  await mk('baseplate', build$9);
  await mk('ground', build$8);
  await mk('road', build$7);
  await mk('crosswalk', build$6);
  await mk('drainage', build$5);
  await mk('sidewalk', build$4);
  await mk('alley', build$3);
  await mk('platform', build$2);
  await mk('track', build$1);
  await mk('crossing', build);
  pruneToClip(map);   // 兜底：地图模块里直接 mesh(box(...)) 自由排布的散件按世界位置收口
  const post0 = performance.now();
  pruneHulls(map, 0.14);
  autoInstance(map, { min: 4 });
  mergeInstances(map);
  traceMark('misc', 'map 收尾(prune/autoInstance/merge)', post0);
  world.add(map);

  /* ---------- 资产层（按 docs/LAYOUT.md 落位） ---------- */
  const assets = grp('assets');
  await placeAll(assets, engine, {
    onProgress(done, total) {
      const [a0, a1] = BOOT_PHASES.assets;
      engine?.markProgress(a0 + (a1 - a0) * (total ? done / total : 0), '摆放店铺与道具');
    },
  });
  const post1 = performance.now();
  markStatic(assets);
  markStatic(map);
  traceMark('misc', 'markStatic', post1);
  world.add(assets);
  if (engine) engine.assetsGroup = assets;
  world.map = map;
  return world;
}

// 天空与环境的程序化生成器：天气模块只提供「六级色阶 + 太阳参数」，这里负责画出来。
// 背景是一条 8×512 的竖向渐变（贴到 scene.background），环境是同构的 equirect 画布
// 过一遍 PMREM。背景每帧可以重画（8 px 宽，成本可忽略），PMREM 不行，所以按天气缓存。

/** 背景用的竖向色阶条。stops 数量固定为 6，天气之间才能逐槽插值。 */
function makeBackdrop(stops) {
  const c = document.createElement('canvas');
  c.width = 8;
  c.height = 512;
  const t = new CanvasTexture(c);
  t.colorSpace = SRGBColorSpace;
  t.magFilter = LinearFilter;
  paintBackdrop(t, stops);
  return t;
}

function paintBackdrop(tex, stops) {
  const c = tex.image;
  const g = c.getContext('2d');
  const gr = g.createLinearGradient(0, 0, 0, c.height);
  stops.forEach((s, i) => gr.addColorStop(i / (stops.length - 1), s.isColor ? '#' + s.getHexString() : s));
  g.fillStyle = gr;
  g.fillRect(0, 0, c.width, c.height);
  tex.needsUpdate = true;
}

/**
 * equirect 天空 → PMREM 环境贴图。
 * sun 为 null 时不画日轮（阴雨/夜晚），否则按 x/y/r/颜色画一团带光晕的高光。
 * clouds.n>0 时叠几层扁椭圆云，alpha 控制云的不透明度。
 * haze 是地平线那一条暖雾带（原 lighting.js 的天空就有，去掉会让低角度反弹光偏冷）。
 */
function makeEnvironment(renderer, cache, { stops, sun, clouds, haze }) {
  if (cache.map) return cache.map;
  const w = 512, h = 256;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d');
  const gr = g.createLinearGradient(0, 0, 0, h);
  stops.forEach((s, i) => gr.addColorStop(i / (stops.length - 1), s.isColor ? '#' + s.getHexString() : s));
  g.fillStyle = gr;
  g.fillRect(0, 0, w, h);
  if (haze) {
    const hg = g.createLinearGradient(0, h * haze.y0, 0, h * haze.y1);
    hg.addColorStop(0, `rgba(${haze.rgb},0)`);
    hg.addColorStop(0.5, `rgba(${haze.rgb},${haze.alpha})`);
    hg.addColorStop(1, `rgba(${haze.rgb},0)`);
    g.fillStyle = hg;
    g.fillRect(0, 0, w, h);
  }
  if (sun) {
    const sx = w * sun.x, sy = h * sun.y;
    const sg = g.createRadialGradient(sx, sy, sun.core || 2, sx, sy, sun.r);
    sg.addColorStop(0, sun.inner);
    sg.addColorStop(0.25, sun.outer);
    sg.addColorStop(1, 'rgba(255,240,206,0)');
    g.fillStyle = sg;
    g.fillRect(0, 0, w, h);
  }
  if (clouds && clouds.n) {
    for (let i = 0; i < clouds.n; i++) {
      const x = Math.random() * w;
      const y = h * (clouds.band[0] + Math.random() * (clouds.band[1] - clouds.band[0]));
      const rw = 40 + Math.random() * 120, rh = 6 + Math.random() * 16;
      const cg = g.createRadialGradient(x, y, 0, x, y, rw);
      cg.addColorStop(0, `rgba(255,255,255,${clouds.alpha})`);
      cg.addColorStop(1, 'rgba(255,255,255,0)');
      g.fillStyle = cg;
      g.save();
      g.translate(x, y);
      g.scale(1, rh / rw);
      g.translate(-x, -y);
      g.beginPath();
      g.arc(x, y, rw, 0, Math.PI * 2);
      g.fill();
      g.restore();
    }
  }
  const tex = new CanvasTexture(c);
  tex.mapping = EquirectangularReflectionMapping;
  tex.colorSpace = SRGBColorSpace;
  const pmrem = new PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  const env = pmrem.fromEquirectangular(tex).texture;
  pmrem.dispose();
  tex.dispose();
  cache.map = env;
  return env;
}

// 湿地面：改的是 toon 内核早就注入好的那组 uniform，不新增着色器分支、不换材质。
//
// 「湿」在画面里其实是三件事：更暗、更饱和、多一层宽而亮的反光。
// 全部按**基准值乘系数**来做，而不是设成固定值 —— 草皮与泥土的 spec 基准本来就低，
// 给它们写死一个高反光会得到一片塑料草坪；乘法让它们只变暗一点、变艳一点。

const base = new WeakMap();
let last = -1;

/** 按 wet ∈ [0,1] 重写所有登记过的铺面材质。wet 没变就直接返回，稳态零开销。 */
function applyWet(w) {
  if (w === last) return;
  last = w;
  for (const mat of WETTABLE) {
    const u = mat.userData && mat.userData.u;
    if (!u || !u.uSpecStrength) continue;
    let b = base.get(mat);
    if (!b) {
      b = { spec: u.uSpecStrength.value, pow: u.uSpecPower.value, cut: u.uSpecCut.value, sat: u.uSat.value, con: u.uContrast.value, sh: u.uShadowAmt.value };
      base.set(mat, b);
    }
    u.uSpecStrength.value = b.spec * (1 + 3.4 * w);
    u.uSpecPower.value = b.pow * (1 - 0.62 * w);
    u.uSpecCut.value = b.cut * (1 - 0.5 * w);
    u.uSat.value = b.sat * (1 + 0.24 * w);
    u.uContrast.value = b.con * (1 + 0.11 * w);
    u.uShadowAmt.value = b.sh * (1 + 0.18 * w);
  }
}

// 天气切换的屏幕控件。
//
// 这是「成品画面零 UI」这条硬性约束的第二次、也是更大的一次让步 —— 第一次是装配期的加载状态，
// 那还在画面之外；这个是常驻可见的。用户明确要求「切换增加ui」，所以按钮是真的，
// 只在指针离开时压到很低的对比度，不玩「 hover 才出现」那种把功能藏起来的把戏。
//
// 按钮列表由天气预设表生成（NAME + LABEL），所以以后加一档天气只改预设文件，这里不用动。
// 预设表由调用方传进来而不是 import：index.js 要 import 本文件，反向 import 会成环。
// 状态回显走每帧一次字符串比较：键盘 1–5 与 ?weather= 也改天气，控件必须跟着动，
// 而给控制器加一套订阅机制换这点开销不值得。

function attachWeatherUI(engine, weather, list) {
  const host = document.getElementById('wxbar');
  if (!host || !weather) return null;

  const buttons = list.map((w) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'wx';
    b.textContent = w.LABEL;
    b.title = w.LABEL;
    b.dataset.name = w.NAME;
    b.addEventListener('click', () => weather.set(w.NAME));
    host.appendChild(b);
    return b;
  });

  let shown = '';
  const sync = () => {
    if (weather.current === shown) return;
    shown = weather.current;
    for (const b of buttons) b.classList.toggle('is-on', b.dataset.name === shown);
    // 夜景上顶着一个白药丸会很刺眼，控件跟着天气换一套明暗配色
    host.classList.toggle('is-dark', !!weather.dark);
  };
  sync();
  engine.onUpdate(sync);
  return { sync };
}

